INSERT INTO `content_fields` VALUES (1,'3d-modeling-rendering','Dark Showcase','dark-showcase.1','Heading: What Our 3D Modeling and Rendering …','text','What Our 3D Modeling and Rendering Services Cover',34,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(2,'3d-modeling-rendering','Hero','hero.1','Image (hero-floor.png)','image','assets/images/3d/hero-floor.png',1,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(3,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.1','Image (viewer-bg.png)','image','assets/images/3d/viewer-bg.png',12,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(4,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.2','Image (technical-panel.png)','image','assets/images/3d/technical-panel.png',13,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(5,'3d-modeling-rendering','Stats','stats.1','Image (why-corner.png)','image','assets/images/3d/why-corner.png',20,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(6,'3d-modeling-rendering','Tools Strip','tools-strip.1','Image (tools-bg-687972.png)','image','assets/images/3d/tools-bg-687972.png',27,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(7,'3d-modeling-rendering','Tools Strip','tools-strip.2','Image: STP, FBX, STL and OBJ file ic… (file-formats.png)','image','assets/images/3d/file-formats.png',28,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(8,'3d-modeling-rendering','Services + Workflow','services-workflow.1','Image: 3D rendering services overview (services.png)','image','assets/images/3d/services.png',33,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(9,'3d-modeling-rendering','What We Offer + CTA + Engagement','what-we-offer-cta-engagement.1','Button text: Let’s Talk','text','Let’s Talk',38,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(10,'3d-modeling-rendering','Hero','hero.2','Paragraph: Home / Services / Animation / 3D Modeling and…','html','<a href=\"index.php\">Home</a> / <a href=\"services.php\">Services</a> / <a href=\"services.php#svc-5\">Animation</a> / <span>3D Modeling and Rendering</span>',2,'2026-10-12 04:39:01','2026-10-13 07:06:40'),(11,'3d-modeling-rendering','Hero','hero.3','Main heading: 3D Modeling and Rendering','text','3D Modeling and Rendering',3,'2026-10-12 04:39:01','2026-10-12 05:58:46'),(12,'3d-modeling-rendering','Hero','hero.4','Paragraph: 3D modeling and rendering turn an idea, sketc…','textarea','3D modeling and rendering turn an idea, sketch, or design file into a precise digital model and photorealistic visuals. This lets you explore form, materials, finishes, lighting, and variations before anything is manufactured or built. You can refine a product, visualize a space, present concepts for approval, and create marketing imagery without producing a physical prototype. For businesses that need to develop, sell, or approve something before it exists, this transforms an abstract idea into something clear and convincing.',4,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(13,'3d-modeling-rendering','Hero','hero.5','Bold label: Dedicated in-house 3D team','text','Dedicated in-house 3D team',5,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(14,'3d-modeling-rendering','Hero','hero.6','Text: Focused on accuracy, realism & on-time delive…','text','Focused on accuracy, realism &amp; on-time delivery.',6,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(15,'3d-modeling-rendering','Hero','hero.7','Heading: Let\'s bring your 3D vision to life.','text','Let\'s bring your 3D vision to life.',7,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(16,'3d-modeling-rendering','Hero','hero.8','Paragraph: Tell us about your project.','text','Tell us about your project.',8,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(17,'3d-modeling-rendering','Hero','hero.9','Text: Subject','text','Subject',9,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(18,'3d-modeling-rendering','Hero','hero.10','Text: Your Message','text','Your Message',10,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(19,'3d-modeling-rendering','Hero','hero.11','Button text: Start a Project','text','Start a Project',11,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(20,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.3','Heading: Selected 3D Modeling and Rendering Work','text','Selected 3D Modeling and Rendering Work',14,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(21,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.4','Text: Drag to Rotate ↔','text','Drag to Rotate &harr;',15,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(22,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.5','Sub-heading: Flexibel','text','Flexibel',16,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(23,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.6','Paragraph: Lorem ipsum dolor sit amet consectetur.','text','Lorem ipsum dolor sit amet consectetur.',17,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(24,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.7','Paragraph: Lorem ipsum dolor sit amet consectetur. Conva…','textarea','Lorem ipsum dolor sit amet consectetur. Convallis sed dui netus suscipit quis. Porttitor ut egestas faucibus consectetur scelerisque magna. Orci adipiscing proin facilisis semper tortor viverra sed nulla duis. Ut eu.',18,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(25,'3d-modeling-rendering','360 Viewer + Selected Work','360-viewer-selected-work.8','Text: Exploded View (button label in the assembled state)','text','Exploded View',19,'2026-10-12 04:39:01','2026-10-23 03:32:49'),(26,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.1','Heading: Why Intelliworkz','text','Why Intelliworkz',21,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(27,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.2','Paragraph: The value of a render is simple: people belie…','textarea','The value of a render is simple: people believe what they can see. A photorealistic image of a product lets a customer picture owning it, lets a stakeholder sign off on it with confidence, and lets your marketing and sales teams start work long before the product reaches a shelf.',22,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(28,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.3','Paragraph: Our team is involved in the entire workflow: …','textarea','Our team is involved in the entire workflow: setting up the model, all the way through to lighting the final image and finishing rendering; we provide a final result suited to its end purpose. For example, a pure studio shot for an online product directory would require very different lighting, composition, and finishing to a studio or scene designed for an advertising creative or a technical render suitable for a stakeholder.',23,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(29,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.4','Paragraph: Because everything is produced by our own tea…','textarea','Because everything is produced by our own team, your designs never leave our hands, which matters when you are rendering a product that has not yet launched. You get consistent quality across every image, and a team that already understands your product by the second project.',24,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(30,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.5','Button text: Enquire Now','text','Enquire Now',26,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(31,'3d-modeling-rendering','Why Intelliworkz','why-intelliworkz.6','Button link: Enquire Now','url','contact-us.php',25,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(32,'3d-modeling-rendering','Services + Workflow','services-workflow.2','Heading: The Renders We Produce','text','The Renders We Produce',29,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(33,'3d-modeling-rendering','Services + Workflow','services-workflow.3','Paragraph: Our 3d product rendering services cover the v…','textarea','Our 3d product rendering services cover the visuals a business needs to sell, present and plan, from a single hero product shot to a full set of images for a catalogue, an online store or a campaign. Some clients send a finished 3D model ready to render; others send a CAD file or a set of drawings for us to model first. Either way, the finished images are built to match how and where you will use them.',30,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(34,'3d-modeling-rendering','Services + Workflow','services-workflow.4','Button text: Enquire Now','text','Enquire Now',32,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(35,'3d-modeling-rendering','Services + Workflow','services-workflow.5','Button link: Enquire Now','url','contact-us.php',31,'2026-10-12 04:39:01','2026-10-12 04:57:18'),(36,'3d-modeling-rendering','What We Offer + CTA + Engagement','what-we-offer-cta-engagement.2','Heading: what we offer','text','what we offer',35,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(37,'3d-modeling-rendering','What We Offer + CTA + Engagement','what-we-offer-cta-engagement.3','Paragraph: Lorem ipsum dolor sit amet consectetur. Portt…','textarea','Lorem ipsum dolor sit amet consectetur. Porttitor egestas leo viverra nec consequat nunc sit cum pretium. Enim iaculis malesuada pharetra risus mattis. Convallis faucibus malesuada vitae pellentesque viverra sagittis. Sed vestibulum volutpat lacus a malesuada lorem dolor sagittis. Suspendisse vitae turpis a magna. Varius a sed a hac hendrerit.',36,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(38,'3d-modeling-rendering','What We Offer + CTA + Engagement','what-we-offer-cta-engagement.4','Heading: Book a Free Consultation','text','Book a Free Consultation',37,'2026-10-12 04:39:01','2026-10-12 04:56:13'),(39,'3d-modeling-rendering','FAQs','faqs.1','Heading: FAQs','text','FAQs',39,'2026-10-12 04:39:01','2026-10-12 04:52:49'),(40,'global','Engagement Model','engagement-model.1','Button text: Let’s Collaborate','text','Let’s Collaborate',1,'2026-10-12 04:39:01','2026-10-12 04:39:01'),