INSERT INTO `content_lists` VALUES (1,'3d-modeling-rendering','td_benefits','Hero','Benefit chips under the intro','[\"Precision-Driven 3D Modeling\",\"Photorealistic Rendering\",\"Production-Ready 3D Assets\",\"Flexible 3D Workflows\"]',5,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(2,'3d-modeling-rendering','td_filters','Gallery','Filter tab names','{\"all\":\"All\",\"wireframe\":\"Wireframe\",\"material\":\"Material Study\",\"detail\":\"Detail View\",\"360\":\"360\\u00b0 View\",\"exploded\":\"Exploded View\"}',19,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(3,'3d-modeling-rendering','td_gallery','Gallery','Gallery images','[{\"img\":\"gallery-1.png\",\"cats\":\"detail\"},{\"img\":\"gallery-2.png\",\"cats\":\"wireframe detail\"},{\"img\":\"gallery-3.png\",\"cats\":\"wireframe\"},{\"img\":\"gallery-4.png\",\"cats\":\"material\"},{\"img\":\"gallery-5.png\",\"cats\":\"material detail\"},{\"img\":\"gallery-featured-4b403a.png\",\"cats\":\"360 exploded\"},{\"img\":\"gallery-6.png\",\"cats\":\"material\"},{\"img\":\"gallery-7.png\",\"cats\":\"detail\"},{\"img\":\"gallery-8.png\",\"cats\":\"material\"},{\"img\":\"gallery-9.png\",\"cats\":\"exploded\"},{\"img\":\"gallery-10.png\",\"cats\":\"exploded detail\"}]',20,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(4,'3d-modeling-rendering','td_stats_top','Numbers','Statistic','[[\"2500\",\"Projects Delivered\"],[\"7\",\"Countries Global Presence\"],[\"30\",\"Industries Served\"]]',30,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(5,'3d-modeling-rendering','td_stats_bottom','Numbers','Statistic','[[\"18\",\"Years of Experience\"],[\"1200\",\"Global Clients\"],[\"120\",\"Skilled Professional\"]]',30,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(6,'3d-modeling-rendering','td_benefit_cards','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"no\":\"01\",\"noc\":\"#7FB5C8\",\"icon\":\"benefit-1.svg\",\"ring\":\"var(--c-teal)\",\"title\":\"In-house 3D Team\",\"text\":\"All 3D modeling and rendering work is handled by our in-house team for consistent quality, control, and communication.\",\"raised\":false},{\"no\":\"02\",\"noc\":\"var(--c-red)\",\"icon\":\"benefit-2.svg\",\"ring\":\"var(--c-red)\",\"title\":\"Dedicated project team\",\"text\":\"The same 3D artist or team works on your project from start to finish, carrying your materials, lighting, and quality standards forward without re-briefing.\",\"raised\":true},{\"no\":\"03\",\"noc\":\"#2D2D2D\",\"icon\":\"benefit-3.svg\",\"ring\":\"var(--c-near-black)\",\"title\":\"Data security\",\"text\":\"Your content, files, and unpublished material are handled under strict security, kept within our team and never shared outside.\",\"raised\":false},{\"no\":\"04\",\"noc\":\"#6B8F3E\",\"icon\":\"benefit-4.svg\",\"ring\":\"var(--c-green)\",\"title\":\"Transparent pricing\",\"text\":\"All design work produced entirely in-house: no freelancers, no subcontracting.\",\"raised\":false}]',40,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(7,'3d-modeling-rendering','td_tools','Tools','Tools','[[\"tool-vray.svg\",\"V-Ray and Corona\",\"Realistic Rendering\"],[\"tool-blender.svg\",\"Blender and Cycles\",\"Creative Flexibility\"],[\"tool-3dsmax.png\",\"3ds Max\",\"Precision Modelling\"],[\"tool-photoshop.svg\",\"Adobe Photoshop\",\"Post Production\"]]',50,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(8,'3d-modeling-rendering','td_tool_formats_label','Tools','Formats label','[\"CAD and model formats\",\"Works with Your Pipeline\"]',51,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(9,'3d-modeling-rendering','td_services','Services','Services accordion','[{\"title\":\"Product Rendering\",\"open\":true,\"points\":[\"Studio-style product images for catalogues and eCommerce\",\"Lifestyle and in-context scenes that show the product in use\",\"Material, colour and finish variations from a single model\",\"Exploded views and close-up detail shots for technical clarity\"]},{\"title\":\"Commercial and Marketing\",\"points\":[\"Hero shots and campaign imagery built around your brand\",\"Consistent visuals across product ranges\",\"Assets sized and formatted for every channel\"]},{\"title\":\"Architectural and Interior\",\"points\":[\"Interior and exterior visualisations for approval and marketing\",\"Material and lighting studies for a space\",\"Walkthrough-ready scenes for presentations\"]}]',60,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(10,'3d-modeling-rendering','td_workflow','Process','Process steps','[{\"no\":\"01\",\"color\":\"var(--c-yellow)\",\"img\":\"step-1-160f4f.png\",\"title\":\"Your files.\",\"text\":\"You send a 3D model, a CAD file, or drawings. If you only have drawings, we build the model first. If the model is ready, we move straight to the scene, and we confirm how the images will be used.\"},{\"no\":\"02\",\"color\":\"var(--c-pink)\",\"img\":\"step-2-51cdb9.png\",\"title\":\"Materials and lighting.\",\"text\":\"We apply accurate materials, colours and finishes to match the real product, then light the scene to suit the setting you want, from a clean studio background to a real-world environment.\"},{\"no\":\"03\",\"color\":\"var(--c-green)\",\"img\":\"step-3.png\",\"title\":\"Draft render.\",\"text\":\"You see a first version at working quality, so you can check the angle, materials and composition before we commit to the final output. Catching a change here saves time later.\"},{\"no\":\"04\",\"color\":\"var(--c-gold)\",\"img\":\"step-4-293cbb.png\",\"title\":\"Review and adjust.\",\"text\":\"You give feedback on the draft, and we refine the materials, lighting, and framing within the agreed rounds. Changes at this stage are quick and inexpensive to make.\"},{\"no\":\"05\",\"color\":\"var(--c-teal)\",\"img\":\"step-5-3348cf.png\",\"title\":\"Final delivery.\",\"text\":\"We render at full resolution, finish each image in post-production, and deliver the files in the sizes and formats you need for print, web, eCommerce, or presentation.\"}]',70,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(11,'3d-modeling-rendering','td_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Product Demo Videos\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Show how your product works through clear demonstrations created with accurate 3D models and rendered scenes.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"3D Animation\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"Bring products, mechanisms and concepts to life with animated sequences that explain movement, assembly and function.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Visual merchandise\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Create polished retail and campaign visuals that present products across displays, environments and promotional formats.\"},{\"no\":\"04\",\"noc\":\"#D9D3A0\",\"bg\":\"linear-gradient(-42deg, #F5F1C4 0%, #FFFEF8 100%)\",\"title\":\"Technical Renders\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Precise technical visuals for stakeholders and manufacturing partners, built directly from your CAD data.\"}]',80,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(12,'3d-modeling-rendering','td_faqs','FAQs','Questions & answers','[[\"What is 3D rendering?\",\"3D rendering is where we produce a photorealistic image or video of a 3D model. Software can add textures to it, a degree of lighting, plus minute details to complete the vision, which will look very real; almost photorealistic. Often used to visualize what an object, a space, or a building will look like before it is even built so that sales can take place in advance.\"],[\"Is 3D rendering difficult?\",\"The process itself takes specialist software and an experienced team, but for you it is straightforward: you send a model or drawings, review a draft, and give feedback within the agreed rounds.\"],[\"Will AI replace 3D rendering?\",\"AI tools can speed up parts of the process, but accurate materials, lighting, and finishing for a specific product or brand still need an experienced in-house team to get right.\"],[\"What software is best for 3D rendering?\",\"We work with V-Ray and Corona for realistic rendering, Blender and Cycles for creative flexibility, and 3ds Max for precision modelling, chosen to suit each project.\"],[\"Why should you use 3D rendering for your business?\",\"A photorealistic image lets a customer picture owning the product, lets a stakeholder sign off with confidence, and lets your marketing and sales teams start work before the product reaches a shelf.\"],[\"What is included in your 3D rendering services?\",\"Model preparation, materials and lighting, a draft render for review, refinement within the agreed rounds, and final delivery in the sizes and formats you need.\"]]',90,'2026-10-12 04:39:01','2026-10-12 05:59:59'),(13,'global','ve_form_fields','Enquiry form','Enquiry form fields','[[\"Full Name\",\"Enter your first name\",\"text\",\"name\"],[\"Company Name\",\"Enter your company name\",\"text\",\"company\"],[\"Email ID\",\"Enter your email ID\",\"email\",\"email\"],[\"Contact Number\",\"Enter your contact number\",\"tel\",\"phone\"]]',2,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(14,'global','engagement_models','Engagement Model','Engagement models','[{\"no\":\"01\",\"title\":\"FTE \\/ <br>Retainership Model\",\"tag\":\"Fixed <br>monthly Cost\",\"color\":\"#6565FE\",\"num_color\":\"#716AFD\",\"img\":\"model-1-64ffad.png\",\"panel\":\"is-image\",\"height\":\"tall\",\"bullets\":[\"Skilled resources are identified and assigned to work on your specific account.\",\"The resource works exclusively on your account for 40 hours every week, in the preferred shift timing of our client.\",\"Resources can be managed directly by you.\",\"A dedicated project manager is assigned as your point of contact.\",\"If you are not happy with a resource\'s performance, we provide a replacement at no extra cost.\",\"You pay a fixed monthly cost for the number of resources you engage.\",\"You can scale up or scale down with a written notice of 30 to 45 days, depending on the number of resources.\"]},{\"no\":\"02\",\"title\":\"GCC Model\",\"tag\":\"30% Advance\",\"color\":\"#E85260\",\"num_color\":\"#F15B65\",\"img\":\"model-2-466154.png\",\"panel\":\"is-radial\",\"height\":\"tall\",\"img_class\":\"is-wide\",\"bullets\":[\"This model lets you set up your own offshore team through a Build, Operate, Deliver (BOT) approach.\",\"You get the advantage of a dedicated offshore team without handling the setup yourself.\",\"We take care of compliance, infrastructure, and hiring on your behalf.\",\"We also manage the overall day-to-day running of the team, so it stays smooth and hands-off for you.\"]},{\"no\":\"03\",\"title\":\"Transaction <br>Model\",\"tag\":\"Pay on Invoice\",\"color\":\"#C8B083\",\"num_color\":\"#CEA16D\",\"img\":\"model-3.png\",\"panel\":\"is-radial\",\"height\":\"short\",\"bullets\":[\"This model fits you well if you do not have consistent orders or tasks to assign.\",\"The cost per unit of delivery is defined after we complete a proof of concept, on a paid or free trial.\",\"We send you a report of the orders delivered in a given month, and you pay on receipt of the invoice.\",\"The job is carried out by competent resources to ensure consistent delivery every time.\"]},{\"no\":\"04\",\"title\":\"One-time \\/ <br>Milestone-based\",\"tag\":\"Hands-off Setup\",\"color\":\"#7CAF9E\",\"num_color\":\"#63B59D\",\"img\":\"model-4.png\",\"panel\":\"is-radial\",\"height\":\"short\",\"img_class\":\"is-wide\",\"bullets\":[\"This model suits you best when you have a large backlog to complete.\",\"We share the cost per unit of delivery and the timeline to complete the order after we perform a proof of concept on a paid or free trial.\",\"You pay an advance, normally 30% of the project cost, with the balance released as per the mutually agreed milestones.\"]}]',4,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(15,'global','showcase_cards','Dark Showcase','Dark showcase slides','[{\"img\":\"showcase-1-f932ad.png\",\"tag\":\"Lifestyle & Travel\",\"tag_color\":\"var(--c-purple)\",\"filled\":true},{\"img\":\"showcase-2.png\",\"tag\":\"Lifestyle & Travel\",\"tag_color\":\"var(--c-purple)\"},{\"img\":\"showcase-3.png\",\"tag\":\"Lifestyle & Travel\",\"tag_color\":\"var(--c-teal)\"},{\"img\":\"showcase-1-f932ad.png\",\"tag\":\"Lifestyle & Travel\",\"tag_color\":\"var(--c-purple)\"}]',3,'2026-10-12 04:39:01','2026-10-12 05:11:48'),(26,'contact-us','ct_offices','Offices','Office details (tabs)','{\"india\":{\"tab\":\"INDIA\",\"country\":\"India\",\"city\":\"Ahmedabad, Gujarat\",\"blocks\":[[[\"Registered Office\",\"Block-B, B912-A, World Trade Tower, Nr. BMW Showroom, SG Highway, Ahmedabad - 380051 Gujarat \\u2013 India.\"]]],\"phone\":\"+91 92740 02997, +91 9427801299\",\"email\":\"hello@intelliworkz.tech\",\"call\":\"+919274002997\",\"blocks2\":[[\"Tech Product Division\",\"Shivalik Corporate Park B Wing, Second Floor 202-202A, 205-205A,Opp. Ashwamedh Bunglows Part 1, Satellite, Ahmedabad 380015\"],[\"Service Division\",\"A Wing, 401-411, World Trade Tower, Nr. BMW Showroom, SG Highway, Ahmedabad - 380051 Gujarat \\u2013 India\"]],\"map\":\"https:\\/\\/www.google.com\\/maps\\/search\\/?api=1&query=World+Trade+Tower+SG+Highway+Ahmedabad\"},\"usa\":{\"tab\":\"USA\",\"country\":\"USA\",\"city\":\"Lewis Center, Ohio\",\"blocks\":[[[\"Office\",\"5511, Mercier Street, Lewis Center, Ohio 43035\"]]],\"phone\":\"+1 614 999 2286\",\"email\":\"hello@intelliworkz.tech\",\"call\":\"+16149992286\",\"blocks2\":[],\"map\":\"https:\\/\\/www.google.com\\/maps\\/search\\/?api=1&query=5511+Mercier+Street+Lewis+Center+Ohio+43035\"},\"dubai\":{\"tab\":\"DUBAI\",\"country\":\"Dubai\",\"city\":\"Sheikh Zayed Road, UAE\",\"blocks\":[[[\"Office\",\"Office No. 25, 13th Floor, Al Saqar Business Tower, Nr. Future Museum, Sheikh Zayed Road, Dubai, UAE.\"]]],\"phone\":\"+971 56 343 5362\",\"email\":\"hello@intelliworkz.tech\",\"call\":\"+971563435362\",\"blocks2\":[],\"map\":\"https:\\/\\/www.google.com\\/maps\\/search\\/?api=1&query=Al+Saqar+Business+Tower+Sheikh+Zayed+Road+Dubai\"}}',10,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(27,'contact-us','ct_pins','Offices','Map labels','[[\"USA\",269.31,546.97,295.04,560.14],[\"Dubai\",567.25,601.49,497.82,573.52],[\"India\",621.2,611.64,646.93,624.81]]',11,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(28,'contact-us','ct_faqs','FAQs','Questions & answers','[[\"What services does Intelliworkz provide?\",\"We provide brand, creative, digital, technology, publishing, post-production, animation, engineering and dedicated team services. The right combination depends on your business requirement, project scope and objectives.\"],[\"Can you handle both one-time projects and ongoing work?\",\"Yes. We work on one-time and milestone-based projects as well as ongoing work, through engagement models such as FTE \\/ retainership, GCC, transaction and one-time.\"],[\"Can I discuss my requirement before deciding to work with you?\",\"Yes. Tell us what you are trying to build, improve, market or manage, and we will understand your requirement, identify the right capabilities and connect you with the right team. Where it helps, we can run a proof of concept on a paid or free trial.\"],[\"Will I have a dedicated team for my project?\",\"Yes. The same or similarly skilled resources work on your orders every time, with a dedicated project manager as your point of contact.\"],[\"Do you outsource the work to freelancers?\",\"No. Our 100% in-house team does not further outsource or engage freelance teams to execute orders, which ensures client confidentiality.\"],[\"Can you work with our existing brand guidelines and materials?\",\"Yes. We work from your brand guidelines and existing content, and address anything missing before design begins.\"],[\"test-1\",\"test-para\"]]',90,'2026-10-12 04:39:01','2026-10-12 07:29:07'),(29,'index','metrics','Hero','Number strip','[{\"icon\":\"icon-send.svg\",\"value\":\"2500\",\"label\":\"Projects Delivered\"},{\"icon\":\"icon-globe.svg\",\"value\":\"7\",\"label\":\"Countries Global Presence\"},{\"icon\":\"icon-briefcase.svg\",\"value\":\"30\",\"label\":\"Industries Served\"},{\"icon\":\"icon-clock.svg\",\"value\":\"18\",\"label\":\"Years of Experience\"},{\"icon\":\"icon-users.svg\",\"value\":\"1200\",\"label\":\"Global Clients\"}]',10,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(30,'index','domains','Services','Service cards','[{\"title\":\"Branding & Creative\",\"color\":\"var(--c-blue)\",\"intro\":\"From brand foundations to digital experiences, we create identities and communication systems that connect with your audience.\",\"items\":[\"Logo Design | logo-design.php\",\"Brand Identity & Design | brand-identity-and-design.php\",\"Marketing and Sales Collaterals | marketing-sales-collaterals.php\",\"Packaging Design | packaging-design.php\",\"Campaign Concepts & Ad Creatives\",\"Corporate Communication\",\"PPT Design | ppt-design.php\",\"Advertising Services\",\"UI\\/UX Design\"],\"cta\":\"Explore Branding & Creative\",\"href\":\"services.php#svc-1\"},{\"title\":\"Digital Marketing & Growth\",\"color\":\"var(--c-orange)\",\"intro\":\"Data-driven digital marketing to help you reach the right audience, generate demand and grow your business online.\",\"items\":[\"Digital Marketing\",\"SEO Services | seo-services.php\",\"AEO Services\",\"GEO Services\",\"Content Marketing\",\"Lead Generation Campaigns\"],\"cta\":\"Explore Digital Marketing\",\"href\":\"services.php#svc-2\"},{\"title\":\"Print & Publication\",\"color\":\"var(--c-purple)\",\"intro\":\"Print-ready artwork, publishing and editorial production for high-quality business and academic communication.\",\"items\":[\"Pre-Press Services | pre-press-service.php\",\"Magazine Design | magazine-design.php\",\"Academic and Technical Publishing Support\",\"Multilingual Publishing and Localization\",\"Product Catalog\",\"InDesign Services\",\"Newsletter Design\"],\"cta\":\"Explore Print & Publication\",\"href\":\"services.php#svc-3\"},{\"title\":\"Post-Production\",\"color\":\"var(--c-charcoal)\",\"intro\":\"Refine footage, imagery and motion assets for polished, production-ready communication.\",\"items\":[\"Video Editing | video-editing.php\",\"Motion Graphics\",\"Explainer Videos\",\"Product Video\"],\"cta\":\"Explore Post-Production\",\"href\":\"services.php#svc-4\"},{\"title\":\"Animation\",\"color\":\"var(--c-olive)\",\"intro\":\"Create engaging motion-led experiences, product demonstrations and 3D visuals for every platform.\",\"items\":[\"Corporate Videos & Shoots\",\"Presentation Videos\",\"3D Modelling & 3D Rendering | 3d-modeling-rendering.php\",\"3D Visualization (Product \\/ Architectural \\/ Industrial)\",\"3D Animation\"],\"cta\":\"Explore Animation\",\"href\":\"services.php#svc-5\"}]',20,'2026-10-12 04:39:01','2026-10-23 23:24:00'),(31,'index','outsourcing_steps','Outsourcing','4-step engagement process','[{\"img\":\"assets\\/images\\/home\\/step-define-the-need.svg\",\"title\":\"Define the Need\",\"text\":\"Project, capability or team requirement defined upfront.\"},{\"img\":\"assets\\/images\\/home\\/step-match-the-expertise.svg\",\"title\":\"Match the Expertise\",\"text\":\"We align the right creative or technical resources.\"},{\"img\":\"assets\\/images\\/home\\/step-integrate-with-your-team.svg\",\"title\":\"Integrate With Your Team\",\"text\":\"Our specialists fit into your tools and processes.\"},{\"img\":\"assets\\/images\\/home\\/step-scale-when-required.svg\",\"title\":\"Scale When Required\",\"text\":\"Increase or reduce capacity as requirements change.\"}]',30,'2026-10-12 04:39:01','2026-10-23 12:25:29'),(32,'index','outsourcing_cards','Outsourcing','Outsourcing cards','[{\"no\":\"01\",\"title\":\"Creative Service Outsourcing\",\"class\":\"is-creative\",\"lead\":\"Extend your creative capacity with professionals working across:\",\"items\":[\"Graphic Design\",\"UI\\/UX Design\",\"Video Editing\",\"3D Visualization & Animation\",\"Branding & Creative Production\",\"Publishing & Pre-Press\"],\"img\":\"outsource-creative.png\"},{\"no\":\"02\",\"title\":\"Engineering & IT Outsourcing\",\"class\":\"is-tech\",\"lead\":\"Bring in specialized technology resources for:\",\"items\":[\"ERP & Custom Software Development\",\"Mobile Application Development\",\"Web Development\",\"eCommerce Development\",\"API & System Integration\",\"Portal Development\",\"Application Maintenance & Support\"],\"img\":\"outsource-tech.png\"},{\"no\":\"03\",\"title\":\"Digital Marketing Outsourcing\",\"class\":\"is-marketing\",\"lead\":\"Extend your marketing team with resources across:\",\"items\":[\"SEO\",\"Social Media\",\"Content\",\"Performance Marketing\",\"Digital Marketing\"],\"img\":\"outsource-marketing.png\"},{\"no\":\"04\",\"title\":\"Dedicated Teams\",\"class\":\"is-dedicated\",\"text\":\"Build a team around your specific requirements with dedicated resources, project management, and the flexibility to scale as your workload changes. The team can work alongside your existing employees, follow your processes, and collaborate within your preferred working structure.\",\"img\":\"outsource-dedicated.png\"}]',31,'2026-10-12 04:39:01','2026-10-23 11:28:20'),(33,'index','industries','Industries','Industry cards','[{\"title\":\"Publication, Pre-press & Print Production\",\"img\":\"assets\\/images\\/home\\/ind-publication.webp\",\"text\":\"Creative artwork, publication design, typesetting, layout adaptation, and pre-press production, packaging artwork for publishers, printers, and print service providers managing high-volume production and tight deadlines.\"},{\"title\":\"Video Production & Post-production\",\"img\":\"assets\\/images\\/home\\/ind-video.webp\",\"text\":\"Professional video editing, colour grading, motion graphics, animation, for brands, agencies, and production houses that need consistent quality, faster turnaround, and scalable post-production support.\"},{\"title\":\"Manufacturing\",\"img\":\"assets\\/images\\/home\\/ind-manufacturing.webp\",\"text\":\"Marketing and Sales collaterals like Product catalogues, technical brochures, product visualizations, packaging design and solution, corporate presentations, industrial photography and product videos that help manufacturers communicate complex products and strengthen their brand presence.\"},{\"title\":\"Finance\",\"img\":\"assets\\/images\\/home\\/ind-finance.webp\",\"text\":\"Brand communication, Monthly factsheets, Investment Insights, monthly investment bulletin, investor reports, Presentation design and adaptation, infographics, digital campaign creatives, and social media content that simplify complex information and build credibility with customers and stakeholders.\"},{\"title\":\"Healthcare\",\"img\":\"assets\\/images\\/home\\/ind-healthcare.webp\",\"img2\":\"ind-education.png\",\"img3\":\"ind-retail.png\",\"video\":\"https:\\/\\/www.youtube.com\\/watch?v=aqz-KE-bpKQ\",\"popup_text\":\"Digital health, patient communication and compliant creative for healthcare brands.\",\"text\":\"Healthcare brochures, medical and product illustrations, patient education materials, presentation design, clinic and hospital communication, digital campaign creatives, SEO and healthcare videos that make information clear, accessible, and engaging.\"},{\"title\":\"Real Estate\",\"img\":\"assets\\/images\\/home\\/ind-real-estate.webp\",\"text\":\"Property brochures, video post-production, architectural visualizations, 3D walkthrough, floor-plan graphics, virtual tours and digital campaign creatives that showcase developments and support property marketing and sales.\"},{\"title\":\"Digital Marketing\",\"img\":\"assets\\/images\\/home\\/ind-digital-marketing.webp\",\"text\":\"Bulk production of Product imagery, eCommerce graphics, product catalogue design, packaging, marketplace creatives, promotional campaigns, and short-form videos that help global digital marketing firms manage their schedule without needing to scale up. And brands create compelling product experiences across digital and retail channels.\"},{\"title\":\"Education\",\"img\":\"assets\\/images\\/home\\/ind-education.webp\",\"text\":\"SEO, Social media creatives, Creative communication, and technology solutions for education-focused organizations.\"}]',40,'2026-10-12 04:39:01','2026-10-23 12:25:29'),(34,'index','reasons','Why Intelliworkz','Reasons to choose us','[[\"100% In-House\",\"Our work is handled by our own team. We do not further outsource or engage freelance teams to execute client requirements.\"],[\"Domain Expertise\",\"Our teams bring domain knowledge across creative, digital, post-production, publishing, and business applications that allows us to understand your requirements, engage and provide tailored solutions.\"],[\"Multiple Capabilities\",\"We provide an array of services under Creative service that includes Graphic design, Digital, Post production support, Animation, Publishing and many more all under one roof.\"],[\"One-Stop-Solution\",\"We act as a one stop solution for all creative and design support for our clients. This saves time of coordinating multiple vendors for similar tasks or workflows.\"],[\"Built to Scale\",\"Your requirement may start with one project or a small team, however as your business grows and there is a dire need to scale, you need to look no further. We can scale-up in short notice with relevant skill sets, which will ensure you continue to grow your business.\"],[\"Consistent Delivery\",\"Our QA process coupled with tailored resources, project management, and well defined workflows help maintain consistency across ongoing engagements.\"]]',50,'2026-10-12 04:39:01','2026-10-23 11:28:20'),(35,'index','products_data','Products','Products','[{\"name\":\"DataNote\",\"tag\":\"ERP, CRM & POS in One Business Platform\",\"text\":\"DataNote brings core business functions together through ERP, CRM, and POS capabilities. It supports areas including inventory, sales, customer engagement, production, procurement, logistics, HR, and administration, helping businesses connect information and manage operations more effectively.\",\"features\":[[\"ERP Framework\",\"Connects inventory, production, procurement, logistics, HR and administration so operations run from one system.\"],[\"CRM Framework\",\"Keeps sales and customer engagement together, so every conversation and follow-up lives in one place.\"],[\"POS\",\"Handles point-of-sale alongside the rest of your business data, so sales feed straight into inventory and reporting.\"],[\"Mobile Apps\",\"Access key business information and tasks from your mobile device, wherever your team works.\"]],\"img\":\"assets\\/images\\/home\\/datanote.webp\"},{\"name\":\"Formezy\",\"tag\":\"Create, Automate & Improve Business Processes\",\"text\":\"Formezy is designed to help businesses create and manage processes more efficiently, bringing form building, data analytics, and integrations together in a user-friendly environment. Its applications extend across areas such as procurement, CRM, production, inventory, and quality control.\",\"features\":[[\"Form Building\",\"\"],[\"Data Analytics\",\"\"],[\"Integrations\",\"\"]],\"img\":\"assets\\/images\\/home\\/formezy.webp\"},{\"name\":\"Docezy\",\"tag\":\"Organize, Store & Share Documents Securely\",\"text\":\"Docezy helps businesses organize, store, and share files through a secure, user-friendly platform. It combines fast uploads and downloads, collaboration, powerful search and retrieval, and security features to make document management easier to handle.\",\"features\":[[\"File Organization\",\"\"],[\"Secure Storage\",\"\"],[\"Collaboration\",\"\"],[\"Search & Retrieval\",\"\"]],\"img\":\"assets\\/images\\/home\\/docezy.webp\"}]',60,'2026-10-12 04:39:01','2026-10-23 12:25:29'),(36,'index','process_row_1','Process','Process cards (top row)','[{\"no\":\"01\",\"color\":\"#53A2BC\",\"bg\":\"#F3F8FA\",\"title\":\"Discovery\",\"img\":\"process\\/process-discovery.png\",\"text\":\"We review your requirements, in line with your business objective, target audience, existing workflow, and expected outcome.\"},{\"no\":\"02\",\"color\":\"#CF6CB9\",\"bg\":\"#FAEFEF\",\"title\":\"Scope\",\"img\":\"process\\/process-scope.png\",\"text\":\"We define the scope of work, determine the right approach, capabilities, resources, technology, and delivery structure.\"},{\"no\":\"03\",\"color\":\"#C9AC61\",\"bg\":\"#FAF6EF\",\"title\":\"Kick-off\",\"img\":\"process\\/process-kickoff.png\",\"text\":\"We identify the right skill set within our team and provide specific training to ensure that we deliver consistent output as per the agreed SLA\\u2019s. The kick-off meeting helps us to align with timelines and quality expectations. We formulate our internal QC document to ensure every project passes through stringent QC before it reaches you.\"}]',70,'2026-10-12 04:39:01','2026-10-23 11:28:20'),(37,'index','process_row_2','Process','Process cards (bottom row)','[{\"no\":\"05\",\"color\":\"#7F68CE\",\"bg\":\"#FAEFFA\",\"title\":\"Scale\",\"img\":\"process\\/process-scale.png\",\"text\":\"As your business grows and you have a need to scale the operations we will ensure that the right resources are in place that cater to your growing needs. Additionally we have tailored our engagement models that are suited to your needs.\"},{\"no\":\"04\",\"color\":\"#59B38D\",\"bg\":\"#ECF9F3\",\"title\":\"Execute\",\"img\":\"process\\/process-execute.png\",\"text\":\"Our team continues to work as per the defined workflow. The project management team will ensure that projects are delivered as per SLA.\"}]',71,'2026-10-12 04:39:01','2026-10-23 11:28:20'),(38,'index','blog_posts','Insights','Insight posts','[{\"img\":\"blog-1.png\",\"date\":\"May 2026\",\"title\":\"How AI Workflows Are Reshaping Global Brand Operations in 2025\"},{\"img\":\"blog-2.png\",\"date\":\"May 2026\",\"title\":\"How AI Workflows Are Reshaping Global Brand Operations in 2025\"},{\"img\":\"blog-3.png\",\"date\":\"May 2026\",\"title\":\"How AI Workflows Are Reshaping Global Brand Operations in 2025\"}]',80,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(39,'magazine-design','mg_benefits','Hero','Benefit chips under the intro','[\"Creative-Driven Efficiency\",\"Deadline-Guaranteed Workflows\",\"Print & Digital Ready\",\"Flexible Engagement Models\"]',5,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(40,'magazine-design','mg_examples','Our Examples','Example strip','[{\"type\":\"blank\"},{\"type\":\"img\",\"img\":\"ex-fashion.png\"},{\"type\":\"frame\",\"img\":\"ex-mockup.png\"},{\"type\":\"img\",\"img\":\"ex-fashion.png\"},{\"type\":\"img\",\"img\":\"ex-magazine.png\"},{\"type\":\"frame\",\"img\":\"ex-mockup.png\"},{\"type\":\"img\",\"img\":\"ex-magazine.png\"},{\"type\":\"blank-border\"}]',20,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(41,'magazine-design','mg_metrics','Numbers','Dark number strip','[[\"m-send.svg\",\"2500\",\"Projects Delivered\"],[\"m-globe.svg\",\"7\",\"Countries Global Presence\"],[\"m-briefcase.svg\",\"30\",\"Industries Served\"],[\"m-clock.svg\",\"18\",\"Years of Experience\"],[\"m-users.svg\",\"1200\",\"Global Clients\"],[\"m-award.svg\",\"120\",\"Skilled Professional\"]]',30,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(42,'magazine-design','mg_why','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"c\":\"var(--c-teal)\",\"no\":\"01\",\"noa\":0.25,\"icon\":\"why-1.svg\",\"shadow\":true,\"border\":false,\"title\":\"In-house design team\",\"text\":\"All design work produced entirely in-house: no freelancers, no subcontracting.\"},{\"c\":\"var(--c-red)\",\"no\":\"02\",\"noa\":0.2,\"icon\":\"why-2.svg\",\"shadow\":true,\"border\":true,\"title\":\"Dedicated project team\",\"text\":\"The same designer or team works on your publication every issue: your standards carry forward without re-briefing.\"},{\"c\":\"var(--c-charcoal)\",\"no\":\"03\",\"noa\":0.15,\"icon\":\"why-3.svg\",\"shadow\":false,\"border\":true,\"title\":\"Data security\",\"text\":\"Your content, files, and unpublished material are handled under strict security, kept within our team and never shared outside.\"},{\"c\":\"var(--c-olive)\",\"no\":\"04\",\"noa\":0.2,\"icon\":\"why-4.svg\",\"shadow\":false,\"border\":true,\"title\":\"Transparent pricing\",\"text\":\"All design work produced entirely in-house: no freelancers, no subcontracting.\"}]',40,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(43,'magazine-design','mg_tools','Tools','Tools','[[\"tool-indesign.svg\",\"#54001A\",\"Adobe InDesign\",\"Layout | Publish\"],[\"tool-illustrator.svg\",\"#330000\",\"Adobe Illustrator\",\"Illustrate | Create\"],[\"tool-photoshop.svg\",\"#001834\",\"Adobe Photoshop\",\"Edit | Retouch\"],[\"tool-figma.svg\",\"#1A1A1A\",\"Figma\",\"Design | Collaborate\"],[\"tool-acrobat.svg\",\"#B40B00\",\"Adobe Acrobat\",\"Review | Share\"]]',50,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(44,'magazine-design','mg_services','Services','Services accordion','[{\"title\":\"Cover Design\",\"open\":true,\"dots\":true,\"points\":[\"Cover concept development from your issue brief\",\"Typography and image composition for the cover\",\"Cover variations for print and digital formats\"]},{\"title\":\"Layout and Editorial Design\",\"points\":[\"Spreads designed section by section against the approved grid\",\"Typography system applied across every page\",\"Captions, pull quotes, and supporting elements set in place\"]},{\"title\":\"Digital Magazine Design\",\"points\":[\"Digital editions exported and tested across devices\",\"Layouts adapted for on-screen reading\",\"Cover variations for digital formats\"]},{\"title\":\"Print Magazine Design\",\"points\":[\"Print-ready PDFs to your printer\'s specifications\",\"Cover variations for print formats\",\"Source files organised for future use\"]},{\"title\":\"Custom Magazine Design\",\"points\":[\"Layouts built around your brief and content plan\",\"Grid, typography and cover format documented to your brand rules\",\"The same team on every issue\"]},{\"title\":\"Template and Style Guide Development\",\"points\":[\"Templates that carry your grid and typography forward\",\"A style guide documenting your brand rules\",\"Source files that your team can edit\"]}]',60,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(45,'magazine-design','mg_flow','Process','Workflow steps','[{\"x\":0,\"y\":14,\"w\":276,\"tw\":245,\"align\":\"left\",\"title\":\"Brief and content plan\",\"text\":\"We confirm the issue scope: theme, content structure, page count, and format. Print, digital, or both are agreed at this stage along with the delivery date.\"},{\"x\":64,\"y\":296,\"w\":313,\"tw\":313,\"align\":\"left\",\"title\":\"Cover concept\",\"text\":\"Cover direction and key design decisions for the issue are developed and approved before internal layout work begins.\"},{\"x\":336,\"y\":539,\"w\":364,\"tw\":364,\"align\":\"left\",\"title\":\"Layout design\",\"text\":\"Spreads are designed section by section against the approved grid and typography system. You review at agreed checkpoints, not at the end when changes become expensive.\"},{\"x\":1094,\"y\":539,\"w\":289,\"tw\":289,\"align\":\"center\",\"title\":\"Content integration\",\"text\":\"Final copy and images are placed into approved layouts. Captions, pull quotes, and supporting elements are set at this stage.\"},{\"x\":1401,\"y\":296,\"w\":274,\"tw\":274,\"align\":\"center\",\"title\":\"Review and revisions\",\"text\":\"You review the full issue and provide consolidated feedback. Revisions are completed within the agreed rounds.\"},{\"x\":1469,\"y\":14,\"w\":302,\"tw\":302,\"align\":\"left\",\"title\":\"Final delivery\",\"text\":\"Print-ready PDFs go to your printer\'s specifications. Digital editions are exported and tested across devices. Source files are transferred on completion, organised for future use.\"}]',70,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(46,'magazine-design','mg_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Desktop Publishing Services\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Document publishing is much more than writing good content; it is about designing the right layouts, formatting, applying the correct typography, and ensuring document preparation is done.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"Newsletter Design\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"A newsletter is not a one-off project. It goes out weekly, monthly, or quarterly, and every time it lands, it either reinforces your brand or quietly undermines it.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Scientific Journal\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Journal publication is the process of having your finished research paper evaluated, approved, and published in a scholarly publication or journal.\"},{\"no\":\"04\",\"noc\":\"#D9D3A0\",\"bg\":\"linear-gradient(-42deg, #F5F1C4 0%, #FFFEF8 100%)\",\"title\":\"Product Catalogue Design\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"A catalogue is only useful when it is easy to browse. We keep product information consistent, accurate, and ready for print and digital output.\"}]',80,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(47,'magazine-design','mg_faqs','FAQs','Questions & answers','[[\"What are magazine design services?\",\"Magazine design services cover the end-to-end design of a publication: cover design, layout design, typography, image treatment, and file preparation for print or digital output. The scope depends on whether you need a single issue or an ongoing production arrangement.\"],[\"What is the difference between print and digital magazine design?\",\"Print files are prepared to your printer\'s specifications. Digital editions are exported and tested across devices. Both can be produced for the same issue.\"],[\"Do you offer custom magazine design or work from templates?\",\"Both. We design custom magazines around your brief, and we develop templates and style guides so your format stays consistent.\"],[\"How long does it take to design a magazine?\",\"The timeline is agreed at the start, once the issue scope, page count, format and delivery date are confirmed.\"],[\"Can you design both the cover and internal layouts?\",\"Yes. The scope covers the cover concept, the internal layouts, and the placement of final copy and images.\"],[\"What file formats do you deliver?\",\"Print-ready PDFs, digital editions, and the source files, organised for future use.\"],[\"Do you handle ongoing issues or only one-off projects?\",\"Both. The same designer or team can work on your publication every issue, so your standards carry forward without re-briefing.\"]]',90,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(48,'manufacturing','mf_lose','Where Manufacturers Lose Ground','\"Where manufacturers lose ground\" cards','[{\"c\":\"var(--c-teal)\",\"tc\":\"var(--c-teal)\",\"title\":\"Brand\",\"img\":\"lose-1.png\",\"box\":[36.7,50.89,506.6,285.11],\"text\":\"When your brand does not reflect the strength of your operation, the right buyers look elsewhere. Not because your product is wrong, but because your presence did not give them a reason to stay.\"},{\"c\":\"#141717\",\"tc\":\"#141717\",\"title\":\"Collateral\",\"img\":\"lose-2.png\",\"box\":[48,65,484.01,272.4],\"text\":\"A well-designed brochure for a manufacturing company does more than list services. It gives the buyer a clear picture of your capability, your standards, and why your business is the right fit, before they have spoken to anyone on your team. \"},{\"c\":\"var(--c-olive)\",\"tc\":\"var(--c-olive)\",\"title\":\"Visibility\",\"img\":\"lose-3.png\",\"box\":[40,57,500,281.4],\"text\":\"Marketing for manufacturing companies works when it reaches the right people at the right moment. We build programmes that put your business in front of industrial buyers when they are actively evaluating suppliers.\"}]',30,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(49,'manufacturing','mf_services','Services','Services accordion','[{\"title\":\"Branding\",\"open\":true,\"text\":\"We build identities that reflect operational credibility. Manufacturing branding services are more than just about a logo. They define how your business is perceived at every touchpoint.\"},{\"title\":\"Digital Marketing\",\"text\":\"Programmes that put your business in front of industrial buyers when they are actively evaluating suppliers.\"},{\"title\":\"Social Media\",\"text\":\"Consistent, credible presence that shows your capability, scale and standards to the buyers researching you.\"},{\"title\":\"Graphic Design\",\"text\":\"Design built around how industrial businesses sell, held to one standard across every piece.\"},{\"title\":\"Brochure Design\",\"text\":\"Brochures that give the buyer a clear picture of your capability and standards before they have spoken to your team.\"},{\"title\":\"Video Production\",\"text\":\"Video that shows what you produce and the scale of your operation, so buyers can evaluate you from your digital presence alone.\"},{\"title\":\"Product Videos\",\"text\":\"Product videos that show your products and process clearly, ready for your website, trade shows and sales conversations.\"}]',60,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(50,'manufacturing','mf_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Brand Identity & Design\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Create a distinctive brand identity through consistent visual design, packaging graphics & creative elements that strengthen brand recognition across every customer touchpoint.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"Marketing & Sales Collaterals\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"Develop professionally designed brochures, catalogues, presentations and promotional materials that communicate your brand support your marketing and sales activities.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Corporate Communication\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Design consistent, brand-aligned corporate materials that help businesses communicate effectively through company profiles, internal publications, professional business documents.\"}]',80,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(51,'manufacturing','mf_faqs','FAQs','Questions & answers','[[\"What does a manufacturing marketing agency do?\",\"A manufacturing marketing agency handles the brand, creative, and digital work that helps manufacturers attract the right buyers and communicate their capability clearly. This covers branding, graphic design, digital marketing, video production, and sales collateral, built around how industrial buying decisions are actually made.\"],[\"Why do manufacturers need specialised marketing?\",\"Because buyers now research suppliers online before any conversation takes place. Every service we offer is built around the buying behaviour and sales cycles specific to manufacturing, rather than adapted from a generic template.\"],[\"What does digital marketing for manufacturers include?\",\"Programmes that put your business in front of industrial buyers when they are actively evaluating suppliers, supported by a website, brand and collateral that show your capability, certifications and scale.\"],[\"How does video production help manufacturers grow?\",\"Video lets buyers see what you produce and the scale of your operation, and helps them judge whether you are the kind of business they want to work with, all from your digital presence.\"],[\"How long does manufacturing marketing take to show results?\",\"It depends on your starting point and market. We shape the work around your specific situation, and agree the scope and priorities with you at the start.\"],[\"Do you work with manufacturers outside India?\",\"Yes. Intelliworkz has a global presence across 7 countries, with offices in India, the USA and Dubai.\"]]',90,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(52,'marketing-sales-collaterals','cl_benefits','Hero','Benefit chips under the intro','[\"Consistent Brand Collateral Design\",\"Print &amp; Digital Marketing Materials\",\"Customisable &amp; Reusable Templates\",\"Sales &amp; Marketing Design Support\"]',5,'2026-10-12 04:39:01','2026-10-13 07:39:05'),(53,'marketing-sales-collaterals','cl_filters','Gallery','Filter tab names','{\"all\":\"All\",\"brochures\":\"Brochures &amp; Catalogues\",\"sales\":\"Sales Collateral\",\"digital\":\"Digital Marketing Materials\"}',19,'2026-10-12 04:39:01','2026-10-13 07:39:05'),(54,'marketing-sales-collaterals','cl_strip','Gallery','Gallery images','[{\"img\":\"strip-a.png\",\"cats\":\"brochures\"},{\"img\":\"strip-b.png\",\"cats\":\"sales\"},{\"img\":\"strip-a.png\",\"cats\":\"digital\"},{\"img\":\"strip-b.png\",\"cats\":\"brochures sales\"},{\"img\":\"strip-a.png\",\"cats\":\"sales digital\"}]',20,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(55,'marketing-sales-collaterals','cl_metrics','Numbers','Dark number strip','[[\"m-send.svg\",\"2500\",\"Projects Delivered\"],[\"m-globe.svg\",\"7\",\"Countries Global Presence\"],[\"m-briefcase.svg\",\"30\",\"Industries Served\"],[\"m-clock.svg\",\"18\",\"Years of Experience\"],[\"m-users.svg\",\"1200\",\"Global Clients\"],[\"m-award.svg\",\"120\",\"Skilled Professional\"]]',30,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(56,'marketing-sales-collaterals','cl_why','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"c\":\"var(--c-teal)\",\"num\":\"#53A2BC\",\"no\":\"01\",\"tab\":\"tab-1.svg\",\"icon\":\"why-1.svg\",\"bg\":\"why-bg-1.png\",\"title\":\"Consistent Brand Standard\",\"text\":\"We design brochures, presentations and proposals to share one clear visual standard across your sales and marketing materials.\"},{\"c\":\"var(--c-red)\",\"num\":\"#E32329\",\"no\":\"02\",\"tab\":\"tab-2.svg\",\"icon\":\"why-2.svg\",\"bg\":\"why-bg-2.png\",\"title\":\"Brand-Led Design\",\"text\":\"Each piece begins with your brand, so colours, typography and messaging stay aligned across every format.\"},{\"c\":\"#141717\",\"num\":\"#141717\",\"no\":\"03\",\"tab\":\"tab-3.svg\",\"icon\":\"why-3.svg\",\"bg\":\"why-bg-3.png\",\"title\":\"Reusable Templates\",\"text\":\"Editable templates help your team produce recurring materials faster while keeping layouts and brand details consistent.\"},{\"c\":\"var(--c-olive)\",\"num\":\"#6B8F3E\",\"no\":\"04\",\"tab\":\"tab-4.svg\",\"icon\":\"why-4.svg\",\"bg\":\"why-bg-4.png\",\"title\":\"Print and Digital Files\",\"text\":\"Receive print-ready and digital files, with source files provided so your team can use and adapt the work.\"}]',40,'2026-10-12 04:39:01','2026-10-13 07:39:05'),(57,'marketing-sales-collaterals','cl_tools','Tools','Tools','[[\"tool-indesign.svg\",\"#54001A\",\"Adobe InDesign\",\"Layout | Publish\"],[\"tool-illustrator.svg\",\"#330000\",\"Adobe Illustrator\",\"Illustrate | Create\"],[\"tool-photoshop.svg\",\"#001834\",\"Adobe Photoshop\",\"Edit | Retouch\"],[\"tool-ppt.png\",null,\"PowerPoint & Google Slides\",\"Design | Present\"],[\"tool-acrobat.svg\",\"#B40B00\",\"Adobe Acrobat\",\"Review | Share\"]]',50,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(58,'marketing-sales-collaterals','cl_services','Services','Services accordion','[{\"title\":\"Marketing Material\",\"points\":[\"Brochures, flyers and leaflets\",\"Company profiles and corporate presentations\",\"Posters, banners and event material\",\"Product catalogues and datasheets\"],\"open\":true},{\"title\":\"Sales Material\",\"points\":[\"Sales decks and pitch presentations\",\"Proposals and quotation templates\",\"Case studies and one-pagers\",\"Product and price sheets\"]},{\"title\":\"Digital Collateral\",\"points\":[\"Editable presentation and document templates\",\"PDFs built for email and download\",\"Social media and campaign graphics\",\"Branded email and newsletter layouts\"]}]',60,'2026-10-12 04:39:01','2026-10-13 07:39:06'),(59,'marketing-sales-collaterals','cl_flow','Process','Workflow steps','[{\"c\":\"#C42030\",\"seg\":0,\"img\":29.33,\"dot\":145,\"tx\":37,\"tw\":230,\"title\":\"1. Brief\",\"text\":\"We begin with what you need, who it is for, and how your team will use it. That defines the format and the approach.\"},{\"c\":\"#CF6CB9\",\"seg\":304,\"img\":337.1,\"dot\":452.77,\"tx\":335.27,\"tw\":230,\"title\":\"2. Brand and content\",\"text\":\"We work from your brand and your content, and address anything missing before design begins.\"},{\"c\":\"#59B38D\",\"seg\":608,\"img\":655.95,\"dot\":771.61,\"tx\":663.61,\"tw\":230,\"title\":\"3. Design\",\"text\":\"We design the piece, or the template, and present it for your review.\"},{\"c\":\"#C9AC61\",\"seg\":912,\"img\":940.35,\"dot\":1056.02,\"tx\":948.02,\"tw\":230,\"title\":\"4. Refinement\",\"text\":\"You share your feedback, and we refine it across the revision rounds we agree upfront.\"},{\"c\":\"#53A2BC\",\"seg\":1216,\"img\":1245.33,\"dot\":1361,\"tx\":1253,\"tw\":230,\"title\":\"5. Delivery\",\"text\":\"We hand over print-ready and digital files, along with editable templates where you need them.\"},{\"c\":\"#7F68CE\",\"seg\":1520,\"img\":1568.76,\"dot\":1684.43,\"tx\":1554.93,\"tw\":269,\"title\":\"6. Ongoing partnership\",\"text\":\"Where the work is continuous, we keep producing new material to the same standard, so your brand stays consistent over time.\"}]',70,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(60,'marketing-sales-collaterals','cl_flow_next','Process','Arrow positions','[291,611,921,1241,1551]',100,'2026-10-12 04:39:01','2026-10-12 05:11:49'),(62,'marketing-sales-collaterals','cl_faqs','FAQs','Questions & answers','[[\"What are marketing and sales collateral design services?\",\"They cover the design of the material your teams use to market and sell, from brochures and presentations to proposals, product sheets and case studies. The purpose is to make every piece clear and credible, so your brand carries weight.\"],[\"What types of marketing and sales collateral do you design?\",\"Brochures, company profiles, presentations, sales decks, proposals, case studies, product and price sheets, banners, event material and digital PDFs, along with editable templates for the pieces your team produces often.\"],[\"Do you provide outsourced sales collateral design for global businesses?\",\"Yes. We work with businesses across regions and time zones, with our team operating in your preferred shift. It makes outsourcing your sales collateral design to us straightforward, with delivery you can depend on.\"],[\"Do you provide B2B marketing and sales collateral design?\",\"Yes, and much of our work is B2B, where the material has to make a detailed offer easy to grasp. We design decks, proposals, and product sheets that give a considered buyer a clear reason to move forward.\"],[\"Can you create white-label marketing and sales collateral for agencies?\",\"Yes. We produce material under your agency\'s brand, with confidentiality agreements in place, ready for you to present to your clients as your own. Our marketing collateral management support lets you hand us regular work and rely on a consistent standard.\"],[\"How can professional sales collateral design help improve sales?\",\"Strong material makes your offer clearer and your business more convincing, which helps a buyer commit. Considered brand identity collateral keeps every touchpoint aligned, so your brand feels established and trustworthy at each stage of the sale.\"]]',90,'2026-10-12 04:39:01','2026-10-13 07:39:06'),(63,'packaging-design','pk_benefits','Hero','Benefit chips under the intro','[\"Creative & Production-Ready Design\",\"Accurate Packaging Artwork\",\"Multi-SKU Packaging Rollouts\",\"Flexible Engagement Models\"]',5,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(64,'packaging-design','pk_filters','Gallery','Filter tab names','{\"all\":\"All\",\"rollout\":\"Packaging Rollout & Product Range Extensions\",\"beauty\":\"Beauty & Skincare Packaging\",\"food\":\"Food & Beverage Packaging\",\"appliance\":\"Appliance & Electronics Packaging\"}',19,'2026-10-12 04:39:02','2026-10-13 06:32:07'),(65,'packaging-design','pk_tiles','Gallery','Work grid','[{\"img\":\"tile-a.png\",\"x\":0,\"y\":0,\"w\":570,\"h\":685,\"ih\":615,\"rollout\":\"tile-b.png\",\"beauty\":\"tile-c.png\",\"food\":\"tile-d.png\",\"appliance\":\"tile-e.png\"},{\"img\":\"tile-b.png\",\"x\":585,\"y\":0,\"w\":600,\"h\":335,\"ih\":258,\"rollout\":\"tile-c.png\",\"beauty\":\"tile-d.png\",\"food\":\"tile-e.png\",\"appliance\":\"tile-f.png\"},{\"img\":\"tile-c.png\",\"x\":1200,\"y\":0,\"w\":600,\"h\":335,\"ih\":258,\"rollout\":\"tile-d.png\",\"beauty\":\"tile-e.png\",\"food\":\"tile-f.png\",\"appliance\":\"tile-a.png\"},{\"img\":\"tile-d.png\",\"x\":585,\"y\":350,\"w\":395,\"h\":335,\"ih\":258,\"rollout\":\"tile-e.png\",\"beauty\":\"tile-f.png\",\"food\":\"tile-a.png\",\"appliance\":\"tile-b.png\"},{\"img\":\"tile-e.png\",\"x\":995,\"y\":350,\"w\":395,\"h\":335,\"ih\":258,\"rollout\":\"tile-f.png\",\"beauty\":\"tile-a.png\",\"food\":\"tile-b.png\",\"appliance\":\"tile-c.png\"},{\"img\":\"tile-f.png\",\"x\":1405,\"y\":350,\"w\":395,\"h\":335,\"ih\":258,\"rollout\":\"tile-a.png\",\"beauty\":\"tile-b.png\",\"food\":\"tile-c.png\",\"appliance\":\"tile-d.png\"}]',20,'2026-10-12 04:39:02','2026-10-13 06:32:07'),(66,'packaging-design','pk_stats','Numbers','Statistics','[[[\"500\",\"+\",\"Packaging Projects<br>Completed\"],[\"1000\",\"+\",\"SKU Variants<br>Adapted\"],[\"150\",\"+\",\"Brands<br>Supported\"]],[[\"98\",\"%\",\"On-Time<br>Delivery\"],[\"250\",\"+\",\"Packaging Formats<br>Handled\"],[\"15\",\"+\",\"Years of<br>Design Expertise\"]]]',30,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(67,'packaging-design','pk_why','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"c\":\"var(--c-teal)\",\"no\":\"01\",\"icon\":\"why-1.svg\",\"bg\":\"why-bg-1.png\",\"title\":\"In-House Design Team\",\"text\":\"Every marketing and sales collateral piece is designed by our in-house team, with no freelancers or subcontracting.\"},{\"c\":\"#E31E36\",\"no\":\"02\",\"icon\":\"why-2.svg\",\"bg\":\"why-bg-2.png\",\"title\":\"Dedicated Design Team\",\"text\":\"The skilled designers work across your marketing materials, maintaining brand consistency without repeated briefing.\"},{\"c\":\"#141717\",\"no\":\"03\",\"icon\":\"why-3.svg\",\"bg\":\"why-bg-3.png\",\"title\":\"Data Security & Confidentiality\",\"text\":\"Your marketing plans, sales materials and confidential business information are handled securely within our in-house team.\"},{\"c\":\"var(--c-olive)\",\"no\":\"04\",\"icon\":\"why-4.svg\",\"bg\":\"why-bg-4.png\",\"title\":\"Flexible & Transparent Pricing\",\"text\":\"Choose an engagement model that suits your design requirements, with the scope and pricing agreed before work begins.\"}]',40,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(68,'packaging-design','pk_tools','Tools','Tools','[[\"tool-indesign.svg\",\"#54001A\",\"Adobe InDesign\",\"Layout | Publish\"],[\"tool-illustrator.svg\",\"#330000\",\"Adobe Illustrator\",\"Illustrate | Create\"],[\"tool-photoshop.svg\",\"#001834\",\"Adobe Photoshop\",\"Edit | Retouch\"]]',50,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(69,'packaging-design','pk_services','Services','Services accordion','[{\"title\":\"Packaging Design\",\"open\":true,\"points\":[\"Custom Packaging Design\",\"Packaging rollout\",\"Custom Box Packaging Design\",\"Product Label Design\",\"Packaging Concepts\",\"Brand Identity Integration\",\"Product Mockups & 3D Visualizations\"]},{\"title\":\"Packaging Rollout\",\"points\":[\"Approved artwork adapted across multiple SKUs\",\"Product variants and packaging formats\",\"Language and artwork localisation\"]}]',60,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(70,'packaging-design','pk_flow','Process','Process steps','[{\"no\":\"01\",\"c\":\"#F6B700\",\"nx\":47.51,\"img\":\"step-1.png\",\"iw\":296,\"ih\":222,\"title\":\"Discovery\",\"text\":\"Understand your products, packaging requirements, brand guidelines, production workflow, and project objectives.\"},{\"no\":\"02\",\"c\":\"#CF6CB9\",\"nx\":34.51,\"img\":\"step-2.png\",\"iw\":310,\"ih\":212,\"title\":\"Design\",\"text\":\"Develop packaging concepts that balance creativity, functionality, and brand consistency.\"},{\"no\":\"03\",\"c\":\"#59B38D\",\"nx\":34.51,\"img\":\"step-3.png\",\"iw\":287.34,\"ih\":198.77,\"title\":\"Packaging Rollout\",\"text\":\"Adapt approved artwork across multiple SKUs, product variants, languages, and packaging formats.\"},{\"no\":\"04\",\"c\":\"#7F68CE\",\"nx\":34.51,\"img\":\"step-4.png\",\"iw\":296,\"ih\":211,\"title\":\"Pre-Press\",\"text\":\"Validate artwork, refine technical specifications, and prepare accurate print-ready files.\"},{\"no\":\"05\",\"c\":\"#53A2BC\",\"nx\":31.01,\"img\":\"step-5.png\",\"iw\":310,\"ih\":217,\"title\":\"Delivery\",\"text\":\"Deliver production-ready artwork that supports faster approvals and efficient manufacturing.\"}]',70,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(71,'packaging-design','pk_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Brand Identity & Design\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Create a distinctive brand identity through consistent visual design, packaging graphics & creative elements that strengthen brand recognition across every customer touchpoint.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"Marketing & Sales Collaterals\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"Develop professionally designed brochures, catalogues, presentations and promotional materials that communicate your brand support your marketing and sales activities.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Corporate Communication\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Design consistent, brand-aligned corporate materials that help businesses communicate effectively through company profiles, internal publications, professional business documents.\"},{\"no\":\"04\",\"noc\":\"#D9D3A0\",\"bg\":\"linear-gradient(-42deg, #F5F1C4 0%, #FFFEF8 100%)\",\"title\":\"Pre-Press Services\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Validated artwork and accurate print-ready files, prepared for a smooth transition from design to press.\"}]',80,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(72,'packaging-design','pk_faqs','FAQs','Questions & answers','[[\"What are packaging design services, and what do they include?\",\"Packaging design services encompass activities such as design of packaging, revisions on current packaging designs and artwork, and preparation of the design for printing. Services may include label design, packaging launch, artwork revision, pre-press assistance, and file preparation. The objective is to ensure that your packaging design is perfect and production-ready.\"],[\"How do I choose the right packaging design company?\",\"Look for a team that understands both the creative and the technical side of packaging: one that designs the artwork, adapts it across SKUs, and prepares print-ready files, working with you and your printers for consistent, on-time delivery.\"],[\"Do you offer custom box packaging design for unique product shapes?\",\"Yes. Our packaging design services include custom box packaging design, packaging concepts, and product mockups and 3D visualizations so you can see the result before production.\"],[\"What makes a luxury packaging design agency different from a standard one?\",\"Technical accuracy and consistency. Luxury packaging depends on precise artwork, brand identity integration and production-ready files that hold up through approval, pre-press and printing without delay.\"],[\"Do you provide product label design along with packaging design?\",\"Yes. Product label design is part of our packaging design services, alongside custom packaging, packaging rollout and pre-press.\"],[\"Can you redesign our existing packaging instead of starting from scratch?\",\"Yes. We handle package redesigns as well as new product launches, adapting approved artwork across multiple SKUs, variants, languages and packaging formats.\"]]',90,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(73,'ppt-design','ppt_benefits','Hero','Benefit chips under the intro','[\"Custom PowerPoint Slide Design\",\"Brand-Aligned Presentations\",\"Clear Charts & Data Visualisation\",\"Fully Editable Presentation Files\"]',5,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(74,'ppt-design','ppt_filters','Gallery','Filter tab names','{\"all\":\"All\",\"corporate\":\"Corporate Presentations\",\"investor\":\"Investor Pitch Decks\",\"sales\":\"Sales Presentations\",\"reports\":\"Business Reports\",\"templates\":\"PowerPoint Templates\",\"training\":\"Training Presentations\"}',19,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(75,'ppt-design','ppt_thumbs','Gallery','Gallery images','[{\"img\":\"thumb-1.png\",\"cats\":\"corporate investor\"},{\"img\":\"thumb-2.png\",\"cats\":\"sales reports\"},{\"img\":\"thumb-3.png\",\"cats\":\"investor sales corporate\"},{\"img\":\"thumb-4.png\",\"cats\":\"templates training\"},{\"img\":\"thumb-5.png\",\"cats\":\"reports training\"}]',20,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(76,'ppt-design','ppt_stats_top','Numbers','Statistic','[[\"2500\",\"Projects Delivered\"],[\"7\",\"Countries Global Presence\"],[\"30\",\"Industries Served\"]]',30,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(77,'ppt-design','ppt_stats_bottom','Numbers','Statistic','[[\"18\",\"Years of Experience\"],[\"1200\",\"Global Clients\"],[\"120\",\"Skilled Professional\"]]',30,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(78,'ppt-design','ppt_why','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"c\":\"var(--c-teal)\",\"tint\":\"#B5DEEB\",\"no\":\"01\",\"icon\":\"why-1.svg\",\"title\":\"In-House Design Team\",\"text\":\"Every presentation is designed by our in-house team, with no freelancers or subcontracting.\"},{\"c\":\"var(--c-red)\",\"tint\":\"#FFD5D9\",\"no\":\"02\",\"icon\":\"why-2.svg\",\"title\":\"Dedicated Presentation Team\",\"text\":\"The same or similarly skilled designers work across your presentations, maintaining your brand style without repeated briefing.\"},{\"c\":\"#141717\",\"tint\":\"#666666\",\"no\":\"03\",\"icon\":\"why-3.svg\",\"title\":\"Data Security & Confidentiality\",\"text\":\"Your presentation content, financial information and unpublished business material stay confidential within our in-house team.\"},{\"c\":\"var(--c-olive)\",\"tint\":\"#8DAC65\",\"no\":\"04\",\"icon\":\"why-4.svg\",\"title\":\"Flexible & Transparent Pricing\",\"text\":\"Choose an engagement model that suits your presentation requirements, with the scope and pricing agreed before work begins.\"}]',40,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(79,'ppt-design','ppt_tools','Tools','Tools','[[[\"svg\",\"tool-powerpoint.svg\",null,\"Microsoft PowerPoint\",\"Design | Present\"],[\"mag\",\"tool-illustrator.svg\",\"#330000\",\"Adobe Illustrator\",\"Illustrate | Refine\"]],[[\"png\",\"tool-slides.png\",null,\"Google Slides\",\"Collaborate | Present\"],[\"mag\",\"tool-photoshop.svg\",\"#001834\",\"Adobe Photoshop\",\"Edit | Enhance\"]],[[\"png\",\"tool-keynote.png\",null,\"Apple Keynote\",\"Create | Showcase\"]]]',50,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(80,'ppt-design','ppt_services','Services','Services accordion','[{\"title\":\"Business and Sales\",\"open\":true,\"points\":[\"Sales and pitch presentations\",\"Company profiles and capability decks\",\"Product and service presentations\",\"Proposal and tender decks\"]},{\"title\":\"Investor and Corporate\",\"points\":[\"Investor pitch decks\",\"Business reports\",\"Corporate presentations\"]},{\"title\":\"Templates and Internal\",\"points\":[\"Custom PowerPoint templates\",\"Internal and training decks\",\"Rebuilds of old or rough decks\"]}]',60,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(81,'ppt-design','ppt_workflow','Process','Process steps','[[\"01\",\"#F6B700\",46,51,\"step-1.png\",25.96,83.58,165.86,122.08,\"Brief\",\"We start with your content, your audience, and what you need the presentation to achieve, so the design has a clear purpose from the outset.\"],[\"02\",\"#CF6CB9\",26,71,\"step-2.png\",25.2,100.31,167.37,88.62,\"Structure\",\"We shape the story and the slide flow, making sure the message is clear and builds in the right order before any design begins.\"],[\"03\",\"#59B38D\",25,72,\"step-3.png\",20,95.62,164.91,98,\"Design\",\"We design each slide to your brand, turning your content into clean, clear visuals and simplifying anything dense or hard to follow.\"],[\"04\",\"#C9AC61\",25,72,\"step-4.png\",16.64,96,167.37,97.23,\"Your feedback\",\"You review the deck, and we refine it across the revision rounds we agree upfront.\"],[\"05\",\"#53A2BC\",22,75,\"step-5.png\",10.5,90.29,167.29,108.66,\"Delivery\",\"We hand over fully editable files, ready to present, along with a reusable template where you need one.\"],[\"06\",\"#7F68CE\",22,75,\"step-6.png\",23.7,97.44,170.37,94.37,\"Ongoing support\",\"Where you present regularly, we keep producing decks to the same standard as you need them, so your presentations stay consistent over time.\"]]',70,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(82,'ppt-design','ppt_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Marketing & Sales Collaterals\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Professionally designed marketing materials and sales presentations that communicate your message clearly and strengthen your brand.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"Corporate Communication\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"Consistent, brand-aligned communication materials that help businesses share information effectively with internal and external audiences.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Advertising Services\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Creative advertising materials designed to capture attention, communicate your brand message and support your marketing campaigns.\"},{\"no\":\"04\",\"noc\":\"#D9D3A0\",\"bg\":\"linear-gradient(-42deg, #F5F1C4 0%, #FFFEF8 100%)\",\"title\":\"Pitch Deck Design\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Investor-ready pitch decks that tell your story in a clear order, one point per slide.\"}]',80,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(83,'ppt-design','ppt_faqs','FAQs','Questions & answers','[[\"What is included in your PPT design services?\",\"Content structuring, slide design, custom icons, charts and data visuals, and a finished deck built to your brand. We can also build a reusable template. You always receive fully editable files, and you can bring us raw content, a draft, or an existing deck to rebuild.\"],[\"In which file formats do you deliver the presentation?\",\"We hand over fully editable files, ready to present. We work in Microsoft PowerPoint, Google Slides and Apple Keynote, and can also deliver a reusable template.\"],[\"Is it safe to outsource confidential presentation content?\",\"Yes. Your presentation content, financial information and unpublished business material stay confidential within our in-house team, with no freelancers or subcontracting.\"],[\"What types of PowerPoint presentations do you design?\",\"Sales and pitch presentations, company profiles and capability decks, product and service presentations, proposal and tender decks, investor decks, business reports, and templates for internal use.\"],[\"Can I outsource PowerPoint design to your team?\",\"Yes. You can hand us raw content, a rough draft, a Word document, or an old deck that needs rebuilding, and we turn it into a finished, professional presentation.\"],[\"Do you design pitch decks and investor presentations?\",\"Yes. We design high-stakes pitches that have to win in one meeting: the story in a clear order, each slide cut down to the one point it needs to make, and the design matched to your brand.\"]]',90,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(84,'pre-press-service','pp_benefits','Hero','Benefit chips under the intro','[\"Accurate Artwork Verification\",\"Professional Colour Management\",\"Preflight & Quality Checks\",\"Production-Ready File Delivery\"]',5,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(85,'pre-press-service','pp_filters','Gallery','Filter tab names','{\"all\":\"All\",\"packaging\":\"Packaging Pre-Press\",\"commercial\":\"Commercial Print\",\"digital\":\"Digital Pre-Press\",\"colour\":\"Colour Management & Proofing\"}',19,'2026-10-12 04:39:02','2026-10-13 07:24:32'),(86,'pre-press-service','pp_strip','Gallery','Gallery images','[{\"img\":\"strip-a.png\",\"cats\":\"packaging\"},{\"img\":\"strip-b.png\",\"cats\":\"commercial\"},{\"img\":\"strip-a.png\",\"cats\":\"digital\"},{\"img\":\"strip-b.png\",\"cats\":\"colour\"},{\"img\":\"strip-a.png\",\"cats\":\"packaging commercial\"}]',20,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(87,'pre-press-service','pp_stats_top','Numbers','Statistic','[[\"2500\",\"Projects Delivered\"],[\"7\",\"Countries Global Presence\"],[\"30\",\"Industries Served\"]]',30,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(88,'pre-press-service','pp_stats_bottom','Numbers','Statistic','[[\"18\",\"Years of Experience\"],[\"1200\",\"Global Clients\"],[\"120\",\"Skilled Professional\"]]',30,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(89,'pre-press-service','pp_why','Why Intelliworkz','\"Why Intelliworkz\" cards','[{\"c\":\"var(--c-teal)\",\"tint\":\"#B5DEEB\",\"no\":\"01\",\"icon\":\"why-1.svg\",\"title\":\"In-House Pre-Press Team\",\"text\":\"Every artwork file is prepared and checked by our experienced in-house pre-press specialists, with no freelancers or subcontracting.\"},{\"c\":\"var(--c-red)\",\"tint\":\"#FFD5D9\",\"no\":\"02\",\"icon\":\"why-2.svg\",\"title\":\"Dedicated Project Team\",\"text\":\"The same or similarly skilled specialists work across your print projects, maintaining technical accuracy and consistency without repeated briefing.\"},{\"c\":\"#141717\",\"tint\":\"#666666\",\"no\":\"03\",\"icon\":\"why-3.svg\",\"title\":\"Data Security & Confidentiality\",\"text\":\"Your artwork files, packaging designs and confidential production information are handled securely within our in-house team.\"},{\"c\":\"var(--c-olive)\",\"tint\":\"#8DAC65\",\"no\":\"04\",\"icon\":\"why-4.svg\",\"title\":\"Flexible & Transparent Pricing\",\"text\":\"Choose an engagement model that suits your pre-press requirements, with the scope, timelines and pricing agreed before work begins.\"}]',40,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(90,'pre-press-service','pp_tools','Tools','Tools','[[[\"mag\",\"tool-illustrator.svg\",\"#330000\",\"Adobe Illustrator\",\"Create | Refine\"],[\"png\",\"tool-esko-artpro.png\",null,\"Esko ArtPro+\",\"Preflight | Optimise\"],[\"svg\",\"tool-gmg.svg\",null,\"GMG Color Management\",\"Calibrate | Match\"]],[[\"mag\",\"tool-indesign.svg\",\"#54001A\",\"Adobe InDesign\",\"Layout | Prepare\"],[\"png\",\"tool-esko-automation.png\",null,\"Esko Automation Engine\",\"Automate | Streamline\"],[\"png\",\"tool-pitstop.png\",null,\"Enfocus PitStop Pro\",\"Preflight | Correct\"]],[[\"mag\",\"tool-photoshop.svg\",\"#001834\",\"Adobe Photoshop\",\"Edit | Enhance\"],[\"mag\",\"tool-acrobat.svg\",\"#B40B00\",\"Adobe Acrobat Pro\",\"Inspect | Validate\"]]]',50,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(91,'pre-press-service','pp_services','Services','Services accordion','[{\"title\":\"Artwork Preparation\",\"open\":true,\"points\":[\"File verification\",\"Resolution and image checks\",\"Font and typography validation\",\"Bleed, margins, and crop mark setup\",\"Layout optimization\"]},{\"title\":\"Print Production Support\",\"points\":[\"Print optimization for offset, flexo, gravure, or digital\",\"Overprinting and trapping checks\",\"Production-ready file delivery\"]},{\"title\":\"Quality Assurance\",\"points\":[\"Digital proofs and pre-flights\",\"Colour, alignment and typo checks\",\"Client review and approval\"]}]',60,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(92,'pre-press-service','pp_flow','Process','Process cards','[{\"no\":\"01\",\"bg\":\"#EFF7FA\",\"c\":\"#53A2BC\",\"iy\":234,\"title\":\"Artwork Review\",\"text\":\"First, we examine your design files. We then use the dimensions, specifications, and production guidelines for the print run and the colors you require to check for any problems before the file gets into production.\"},{\"no\":\"02\",\"bg\":\"#FAEFEF\",\"c\":\"#CF6CB9\",\"iy\":234,\"title\":\"File Preparation\",\"text\":\"After that, artwork will be prepared, where we will be checking image quality and resolution, fonts used, bleed settings, profiles used, etc., and also overprinting and trapping will be checked; layout is also checked.\"},{\"no\":\"03\",\"bg\":\"#FAF6EF\",\"c\":\"#C9AC61\",\"iy\":263.23,\"title\":\"Proofing & Quality Checks\",\"text\":\"Digital proofs & pre-flights: they run a check for color(s), alignment(s), and typos and check for any technical problem(s) & omissions (the \\u2018pre\\u2019 phase for pre-press).\"},{\"no\":\"04\",\"bg\":\"#EFF7FA\",\"c\":\"#59B38D\",\"iy\":234,\"title\":\"Print Optimization\",\"text\":\"The artwork file is adapted for the print method of choice (offset, flexo, gravure, or digital) so as to enable an accurate color result and efficient production.\"},{\"no\":\"05\",\"bg\":\"#FAEFFA\",\"c\":\"#7F68CE\",\"iy\":234,\"title\":\"Client Review & Approval\",\"text\":\"Final proofs are then sent out for production approval. Any necessary amendments are made to ensure artwork complies with specifications and the brand.\"},{\"no\":\"06\",\"bg\":\"#FAF6EF\",\"c\":\"#53A2BC\",\"iy\":234,\"title\":\"Production-Ready Delivery\",\"text\":\"Files are then delivered as final, ready-to-print; specifications will transition seamlessly to the printing stage.\"}]',70,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(93,'pre-press-service','pp_offers','What We Offer','\"What we offer\" cards','[{\"no\":\"01\",\"noc\":\"#D1C7E6\",\"bg\":\"linear-gradient(-42deg, #EAE2F3 0%, #FBF8FF 100%)\",\"title\":\"Desktop Publishing Services\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"Document publishing is much more than writing good content; it is about designing the right layouts, formatting, applying the correct typography, and ensuring document preparation is done.\"},{\"no\":\"02\",\"noc\":\"#EAD3C4\",\"bg\":\"linear-gradient(-42deg, #FBE7DB 0%, #FFFDFD 100%)\",\"title\":\"Newsletter Design\",\"img\":\"offer-2-56586a.png\",\"x\":45,\"y\":265,\"w\":486,\"h\":372,\"arrow\":\"offer-arrow-2.svg\",\"text\":\"A newsletter is not a one-off project. It goes out weekly, monthly, or quarterly, and every time it lands, it either reinforces your brand or quietly undermines it.\"},{\"no\":\"03\",\"noc\":\"#A2DDDD\",\"bg\":\"linear-gradient(-42deg, #C5E3E3 0%, #F0FAFB 100%)\",\"title\":\"Scientific Journal\",\"img\":\"offer-3-56586b.png\",\"x\":34,\"y\":265,\"w\":505,\"h\":343,\"arrow\":\"offer-arrow-3.svg\",\"text\":\"Journal publication is the process of having your finished research paper evaluated, approved, and published in a scholarly publication or journal.\"},{\"no\":\"04\",\"noc\":\"#D9D3A0\",\"bg\":\"linear-gradient(-42deg, #F5F1C4 0%, #FFFEF8 100%)\",\"title\":\"Product Catalogue Design\",\"img\":\"offer-1-625569.png\",\"x\":58,\"y\":277,\"w\":457,\"h\":341,\"arrow\":\"offer-arrow-1.svg\",\"text\":\"A catalogue is only useful when it is easy to browse. We keep product information consistent, accurate, and ready for print and digital output.\"}]',80,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(94,'pre-press-service','pp_faqs','FAQs','Questions & answers','[[\"What are pre-press services?\",\"Pre-press services involve preparing digital artwork for printing through processes such as file verification, colour management, proofing, layout validation, and print optimization. This ensures every file is technically ready before production begins.\"],[\"What is included in professional pre-press services?\",\"Artwork review, file preparation (resolution, fonts, bleed, colour profiles, overprinting and trapping), proofing and quality checks, print optimization, client review and approval, and production-ready delivery.\"],[\"How long does the pre-press process take?\",\"The timeline depends on the number of files and how much preparation each one needs. It is agreed with you before work begins, together with the scope and pricing.\"],[\"What software is used for pre-press?\",\"We work with Adobe Illustrator, InDesign, Photoshop and Acrobat Pro, Esko ArtPro+ and Automation Engine, GMG colour management, and Enfocus PitStop Pro.\"],[\"What industries use pre-press services?\",\"Any business that prints: packaging and label printers, commercial print, marketing collateral, brochures and wide-format display work.\"],[\"Do I need pre-press services for digital printing?\",\"Yes. Colour shifts, low-resolution images, missing fonts and incorrect layouts cause problems in digital printing too. A pre-press check catches them before the first page is printed.\"]]',90,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(95,'seo-services','seo_benefits','Hero','Benefit chips under the intro','[\"Qualified Lead Generation\",\"End-to-End SEO Management\",\"Launch & Migration Support\",\"Multi-Region SEO Campaigns\"]',5,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(96,'seo-services','seo_filters','Gallery','Filter tab names','{\"all\":\"All\",\"strategy\":\"SEO Strategy\",\"leads\":\"Lead Generation\",\"launches\":\"Website Launches\",\"migrations\":\"Migrations\",\"content\":\"Content SEO\",\"multi\":\"Multi-Region\"}',19,'2026-10-12 04:39:02','2026-10-12 05:11:49'),(97,'seo-services','seo_gallery','Gallery','Gallery images','[{\"img\":\"thumb-1.png\",\"cats\":\"strategy\"},{\"img\":\"thumb-2.png\",\"cats\":\"leads\"},{\"img\":\"t